// Define the parametric surface function
void parametricSurface(float u, float v, float *x, float *y, float *z) {
    *x = cos(u) * cos(v);
    *y = sin(u) * cos(v);
    *z = sin(v);
}

// Function to draw the surface
void drawSurface() {
    int i, j;
    float u, v, du = 0.1, dv = 0.1;
    float x1, y1, z1, x2, y2, z2, x3, y3, z3, x4, y4, z4;

    glBegin(GL_QUADS);
    for (u = 0.0; u < 2 * M_PI; u += du) {
        for (v = 0.0; v < 2 * M_PI; v += dv) {
            parametricSurface(u, v, &x1, &y1, &z1);
            parametricSurface(u + du, v, &x2, &y2, &z2);
            parametricSurface(u + du, v + dv, &x3, &y3, &z3);
            parametricSurface(u, v + dv, &x4, &y4, &z4);

